package main

import (
	"os"
	"path/filepath"
	"testing"
)

// TestInstallPayloadWritesTheBinaries checks the whole payload path: the
// embedded files, the platform list and what ends up in the install directory.
// It needs a build first, because the payload is generated by build.go.
func TestInstallPayloadWritesTheBinaries(t *testing.T) {
	names := payloadFiles()
	for _, name := range names {
		if _, err := payloadFS.ReadFile("payload/" + name); err != nil {
			t.Skipf("no %s in the payload: run 'go run build.go' first", name)
		}
	}

	dir := t.TempDir()
	if err := installPayload(dir); err != nil {
		t.Fatalf("installPayload: %v", err)
	}

	for _, name := range names {
		info, err := os.Stat(filepath.Join(dir, name))
		if err != nil {
			t.Fatalf("expected %s in the install directory: %v", name, err)
		}
		if info.Size() < 100_000 {
			t.Errorf("%s looks too small to be a binary (%d bytes)", name, info.Size())
		}
	}

	// The placeholder only exists so the package compiles; it must never be
	// installed.
	if _, err := os.Stat(filepath.Join(dir, payloadPlaceholder)); !os.IsNotExist(err) {
		t.Errorf("%s must not be installed", payloadPlaceholder)
	}
}
